function drawmesonspectrum(containerId, data) {
    const glowGreen = '#39ff14';
    const textGreen = '#00cc44';
    const dimGreen = '#008822';

    //set up dimensions and margins for the chart
    const margin = { top: 20, right: 20, bottom: 44, left: 56 };
    const width = 640;
    const height = 340;
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    // create the container for the chart and clear any existing content
    const container = d3.select(containerId);
    container.selectAll('*').remove();

    if (!Array.isArray(data) || data.length === 0) return;

    const yValues = data
        .flatMap(d => [d.surrogateMass, d.expMass])
        .filter(v => Number.isFinite(v));

    if (yValues.length === 0) return;

    const yMin = d3.min(yValues);
    const yMax = d3.max(yValues);
    const yPad = Math.max((yMax - yMin) * 0.2, 0.1);

    const svg = container
        .append('svg')
        .attr('viewBox', `0 0 ${width} ${height}`)
        .attr('preserveAspectRatio', 'xMidYMid meet');

    const g = svg
        .append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

    const baseMesonName = d => (d.name || '')
        .replace(/\s*\(\s*\d+\s*[sS]\s*\)\s*$/, '')
        .trim();

    const extractState = d => {
        const match = (d.name || '').match(/\((\d+\s*[sS])\)\s*$/);
        return match ? match[1].replace(/\s+/g, '').toUpperCase() : '';
    };

    const mesonData = data.map(d => ({
        ...d,
        meson: baseMesonName(d),
        state: extractState(d)
    }));

    const xCategories = Array.from(new Set(mesonData.map(d => d.meson)));
    const xScale = d3.scalePoint()
        .domain(xCategories)
        .range([0, innerWidth])
        .padding(0.5);

    const yScale = d3.scaleLinear()
        .domain([yMin - yPad, yMax + yPad])
        .nice()
        .range([innerHeight, 0]);

    g.append('g')
        .attr('transform', `translate(0,${innerHeight})`)
        .call(d3.axisBottom(xScale))
        .style('font-size', '12px');

    g.append('g')
        .call(d3.axisLeft(yScale))
        .style('font-size', '12px');

    g.selectAll('.domain, .tick line')
        .attr('stroke', dimGreen);

    g.selectAll('.tick text')
        .attr('fill', textGreen);

    g.append('text')
        .attr('transform', 'rotate(-90)')
        .attr('y', -44)
        .attr('x', -innerHeight / 2)
        .attr('text-anchor', 'middle')
        .style('font-size', '12px')
        .attr('fill', textGreen)
        .text('Mass [GeV]');

    const legend = g.append('g')
        .attr('transform', `translate(${innerWidth - 150}, -6)`);

    legend.append('line')
        .attr('x1', 0)
        .attr('x2', 26)
        .attr('y1', 0)
        .attr('y2', 0)
        .attr('stroke', glowGreen)
        .attr('stroke-width', 2);

    legend.append('text')
        .attr('x', 32)
        .attr('y', 4)
        .style('font-size', '11px')
        .attr('fill', textGreen)
        .text('Surrogate');

    legend.append('line')
        .attr('x1', 0)
        .attr('x2', 26)
        .attr('y1', 18)
        .attr('y2', 18)
        .attr('stroke', textGreen)
        .attr('stroke-width', 2)
        .attr('stroke-dasharray', '4 3');

    legend.append('text')
        .attr('x', 32)
        .attr('y', 22)
        .style('font-size', '11px')
        .attr('fill', textGreen)
        .text('Experimental');

    const lineHalfWidth = 20;

    g.selectAll('.surrogate-line')
        .data(mesonData.filter(d => Number.isFinite(d.surrogateMass)))
        .enter()
        .append('line')
        .attr('class', 'surrogate-line')
        .attr('x1', d => xScale(d.meson) - lineHalfWidth)
        .attr('x2', d => xScale(d.meson) + lineHalfWidth)
        .attr('y1', d => yScale(d.surrogateMass))
        .attr('y2', d => yScale(d.surrogateMass))
        .attr('stroke', glowGreen)
        .attr('stroke-width', 2);

    g.selectAll('.observed-line')
        .data(mesonData.filter(d => Number.isFinite(d.expMass)))
        .enter()
        .append('line')
        .attr('class', 'observed-line')
        .attr('x1', d => xScale(d.meson) - lineHalfWidth)
        .attr('x2', d => xScale(d.meson) + lineHalfWidth)
        .attr('y1', d => yScale(d.expMass))
        .attr('y2', d => yScale(d.expMass))
        .attr('stroke', d => d.color || textGreen)
        .attr('stroke-width', 2)
        .attr('stroke-dasharray', '4 3');

    g.selectAll('.exp-label')
        .data(mesonData.filter(d => Number.isFinite(d.expMass)))
        .enter()
        .append('text')
        .attr('class', 'exp-label')
        .attr('x', d => xScale(d.meson) - lineHalfWidth - 6)
        .attr('y', d => yScale(d.expMass) + 4)
        .attr('text-anchor', 'end')
        .style('font-size', '10px')
        .style('fill', textGreen)
        .text(d => `exp ${d.expMass.toFixed(3)}`);

    g.selectAll('.state-label')
        .data(mesonData.filter(d => Number.isFinite(d.surrogateMass)))
        .enter()
        .append('text')
        .attr('class', 'state-label')
        .attr('x', d => xScale(d.meson) + lineHalfWidth + 6)
        .attr('y', d => yScale(d.surrogateMass) + 4)
        .attr('text-anchor', 'start')
        .style('font-size', '11px')
        .style('font-style', 'italic')
        .style('fill', glowGreen)
        .text(d => [d.state ? `(${d.state})` : '', d.jp].filter(Boolean).join(' '));
}
